/* 표 검사 — 문제가 있으면 그 까닭(문장), 없으면 "". 커트는 위에서 아래로 줄고, 안정권은 0(없음)이거나 커트 이상 */
function rankTierCheck(rows) {
  if (!Array.isArray(rows) || rows.length < 2 || rows.length > 20) return "구간은 2 ~ 20개여야 해요";
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i];
    if (!r || typeof r.n !== "string" || !r.n.trim()) return (i + 1) + "번째 구간 이름이 비었어요";
    if (typeof r.cut !== "number" || !isFinite(r.cut) || r.cut <= 0) return r.n + " 커트 점수가 비었거나 0 이하예요";
    var sf = r.safe || 0;
    if (typeof sf !== "number" || !isFinite(sf) || sf < 0) return r.n + " 안정권 점수가 이상해요";
    if (sf > 0 && sf < r.cut) return r.n + " 안정권(" + sf + ")이 커트(" + r.cut + ")보다 낮아요";
    if (i > 0 && r.cut >= rows[i - 1].cut) return r.n + " 커트(" + r.cut + ")는 위 구간 " + rows[i - 1].n + " 커트(" + rows[i - 1].cut + ")보다 낮아야 해요";
  }
  return "";
}
/* 지금 쓰는 신버전 표 — 관리자가 저장한 표(버전이 맞고 검사를 통과할 때) 아니면 코드 표 */
function rankTiersOf(sk) {
  var t = sk && sk.rankTiers;
  return (t && (t._v || 0) >= RANK_TIER_VERSION && !rankTierCheck(t.rows)) ? t.rows : RANK_TIERS_CODE;
}
/* 점수 → 예상 구간 (rows 는 커트 높은 순).
   i: 커트를 넘은 가장 높은 구간 (-1 = 맨 아래 커트도 못 넘음) · safe: 그 구간 안정권인지 ·
   safeAt: 안정권에 든 가장 높은 구간 (-1 = 없음) · next: 다음 목표 { label, gap } (맨 위 구간이면 null) */
function rankTierOf(score, rows) {
  var i = -1, safeAt = -1, k;
  for (k = 0; k < rows.length; k++) { if (score >= rows[k].cut) { i = k; break; } }
  for (k = 0; k < rows.length; k++) { if (rows[k].safe > 0 && score >= rows[k].safe) { safeAt = k; break; } }
  var safe = i >= 0 && rows[i].safe > 0 && score >= rows[i].safe;
  var next = null, last = rows[rows.length - 1];
  if (i < 0) next = { label: last.n + " 커트", gap: last.cut - score };
  else if (!safe && rows[i].safe > 0) next = { label: rows[i].n + " 안정권", gap: rows[i].safe - score };
  else if (i > 0) next = { label: rows[i - 1].n + " 커트", gap: rows[i - 1].cut - score };
  return { i: i, row: i >= 0 ? rows[i] : null, safe: safe, safeAt: safeAt, next: next };
}
/* 구간 색 — 이름의 등수로: 30 안 금색 · 100 안 분홍 · 500 안 파랑 · 1000 안 초록 · 그 밖 회색 (어두운 · 밝은 화면 모두 읽히는 중간 밝기) */
function rankTierColor(row) {
  var m = row && String(row.n).match(/\d+/); var v = m ? Number(m[0]) : 99999;
  return v <= 30 ? "#D97706" : v <= 100 ? "#EC4899" : v <= 500 ? "#3B82F6" : v <= 1000 ? "#16A34A" : "#64748B";
}
function rankHexA(hex, a) {
  var n = parseInt(String(hex).slice(1), 16);
  return "rgba(" + ((n >> 16) & 255) + "," + ((n >> 8) & 255) + "," + (n & 255) + "," + a + ")";
}
/* 구간을 보여 줄 만큼 덱이 채워졌는지 — 훈련은 0일 수 없어 0 이면 안 넣은 것 (2026-10-22 사용자 지정: 인내가 빈 덱이 많다).
   타자 파워 · 정확 · 선구 · 인내, 투수 변화 · 구위 · 제구가 모두 1 이상이어야 한다.
   포특 · 라커룸 · 특훈은 0 이 정상일 수 있어 보지 않는다 (막으면 안 된다). 빈 칸 이름 목록을 돌려준다 (다 찼으면 []).
   예외 — 불펜(중계 RP1~6 · 마무리 CP)의 국가대표 카드는 훈련을 일부러 안 찍는 경우가 많다 (2026-10-23 사용자 지정).
   셋(변화 · 구위 · 제구)이 모두 0 이면 '안 찍음'으로 보고 막지 않는다. 일부만 0 이면(거의 다 새로 생긴 제구만 빈 경우) 예전처럼 빈 칸으로 센다.
   10-23 저장 덱: 불펜 국대 훈련 전부 0 은 451장(대부분 롱릴), 일부만 0 은 1,012장 중 1,005장이 제구만 빔. slot 은 라인업 자리 (없으면 예외 없음) */
var RANK_TRAIN_BAT = [["trainP", "파워"], ["trainA", "정확"], ["trainE", "선구"], ["trainN", "인내"]];
var RANK_TRAIN_PIT = [["trainC", "변화"], ["trainS", "구위"], ["trainCtl", "제구"]];
var RANK_TRAIN_FREE_SLOTS = { RP1: 1, RP2: 1, RP3: 1, RP4: 1, RP5: 1, RP6: 1, CP: 1 };
function rankTrainFree(pl, slot) { return !!pl && pl.role === "투수" && pl.cardType === "국가대표" && !!RANK_TRAIN_FREE_SLOTS[slot]; }
function rankTrainMissing(pl, slot) {
  if (!pl) return [];
  var keys = pl.role === "투수" ? RANK_TRAIN_PIT : RANK_TRAIN_BAT;
  var miss = keys.filter(function (k) { return !((Number(pl[k[0]]) || 0) > 0); }).map(function (k) { return k[1]; });
  if (miss.length === keys.length && rankTrainFree(pl, slot)) return [];
  return miss;
}
/* ═══ 랭킹챌린지 예상 구간 끝 ═══ */
async function sGet(k){try{var r=await window.storage.get(k);return r?JSON.parse(r.value):null;}catch(e){return null;}}
async function sSet(k,d){try{await window.storage.set(k,JSON.stringify(d));return true;}catch(e){return false;}}
/* 게스트 id 는 uuid 가 아니라 서버가 받지 않는다 — 브라우저에만 담아야 한다 */
function isGuestUid(uid){ return !uid || String(uid).indexOf("guest_") === 0; }

/* 되돌리기용 스냅샷 — 시트 가져오기처럼 한 번에 많이 갈아엎는 작업 직전에 남긴다.
   덱마다 마지막 하나만 들고 있으면 충분하다. 브라우저에만 저장한다. */
function snapKey(deckId){ return "deck-snapshot-" + deckId; }
/* owner — 그 스냅샷을 남긴 계정. 이 브라우저의 저장소는 계정 구분이 없어서, 같은 덱 id 를 물려받은 다른 계정·게스트가
   남긴 스냅샷으로 "되돌리기"를 하면 남의 내용이 내 덱에 저장된다. 주인이 다르거나 적혀 있지 않은 스냅샷은 없는 것으로 친다 */
async function saveDeckSnapshot(deckId, label, data, owner){
  if(!deckId) return false;
  return await sSet(snapKey(deckId), { ts: Date.now(), label: label || "", data: data, owner: owner || "" });
}
async function loadDeckSnapshot(deckId, owner){
  if(!deckId) return null;
  var v = await sGet(snapKey(deckId));
  return (v && v.owner && v.owner === (owner || "")) ? v : null;
}
async function clearDeckSnapshot(deckId){ if(deckId) await sSet(snapKey(deckId), null); }
function snapAgo(ts){
  var m = Math.floor((Date.now() - ts) / 60000);
  if (m < 1) return "방금";
  if (m < 60) return m + "분 전";
  var h = Math.floor(m / 60);
  return h < 24 ? h + "시간 전" : Math.floor(h / 24) + "일 전";
}

/* ================================================================
   CALCULATION
   ================================================================ */
/* ── 발사각 보너스 (2026-10-19 사용자 지정 수치 업데이트) ───────────
   발사각 13 미만이면 없음.
   필요파워 = 13~16도 162 · 17도 165 · 18도 168 · 그 뒤 1도마다 +3 (22도 180).
   스킬 보정 = 스킬점수 45점 +1 · 48점 +2 · 51점 +3 … (3점마다 +1).
     필요파워를 넘었는지 볼 때만 최종파워에 더한다 — 점수에 들어가는 파워는 그대로.
   보너스   = 13~14도 +3 · 15~18도 +7 · 19도 이상 +5.
   (예전 260814 시트: 필요파워 |16-발사각|*3+160, 보너스 13도 1 ~ 18도 이상 5)   */
/* 선수도감 양식의 「핫콜존」 칸을 흰존/콜존 개수로 푼다.
   예: "흰3" → 흰 3, "파1흰2" → 콜 1 / 흰 2, "파2" → 콜 2, "0"·빈칸 → 0
   파(파란색)가 콜드존이다. */
function parseHotColdZone(v) {
  var t = String(v == null ? "" : v).trim();
  if (!t || t === "0") return { whiteZone: 0, coldZone: 0 };
  var w = /흰\s*(\d+)/.exec(t);
  var c = /파\s*(\d+)/.exec(t);
  return { whiteZone: w ? parseInt(w[1], 10) : 0, coldZone: c ? parseInt(c[1], 10) : 0 };
}

/* 양식이 「핫콜존」 한 칸이든 「흰존」·「콜존」 두 칸이든 받는다.
   두 칸이 있으면 그걸 쓰고, 없으면 핫콜존 문자열을 푼다. */
function zonesFromRow(row) {
  var hasSplit = (row["흰존"] !== undefined && row["흰존"] !== "") ||
                 (row["콜존"] !== undefined && row["콜존"] !== "");
  if (hasSplit) {
    return { whiteZone: parseInt(row["흰존"]) || 0, coldZone: parseInt(row["콜존"]) || 0 };
  }
  return parseHotColdZone(row["핫콜존"]);
}

function launchAngleReq(la){ la=la||0; return la<13?null:(la<=16?162:162+(la-16)*3); }
function launchAngleBonus(la){
  la=la||0; if(la<13)return 0;
  return la<=14?3:la<=18?7:5;
}
/* 스킬점수는 소수 둘째 자리로 맞춰서 본다 (세 스킬을 더하면 47.99999 처럼 떨어질 수 있다) */
function launchAngleSkillAdj(ss){
  var s=Math.round((ss||0)*100)/100;
  return s<45?0:Math.floor((s-45)/3+1e-9)+1;
}
function launchAngleGain(la,finalPower,ss){
  var req=launchAngleReq(la);
  return (req!==null && finalPower+launchAngleSkillAdj(ss)>=req) ? launchAngleBonus(la) : 0;
}
