var ORDER_RENAME = {"선봉장(타순배치,주루142+)": "선봉장(타순O,주루142+)", "선봉장(타순배치,주루130~141)": "선봉장(타순O,주루130~141)", "선봉장(타순배치,주루129이하)": "선봉장(타순O,주루129이하)", "선봉장(타순배치X,주루142+)": "선봉장(타순X,주루142+)", "선봉장(타순배치X,주루130~141)": "선봉장(타순X,주루130~141)", "선봉장(타순배치X,주루129이하)": "선봉장(타순X,주루129이하)", "컨택트히터(타순배치)": "컨택트히터(타순O)", "선봉장(타순O)": "선봉장(타순O,주루142+)", "선봉장(타순배치X)": "선봉장(타순X,주루142+)"};
