  var t = skillTables()[cat]; var a = t && t[name];
  if(!a && t){ var al = SKILL_ALIAS[cat] && SKILL_ALIAS[cat][name]; if(al) a = t[al]; }
  /* 구버전에서 옛 표에 없는 스킬은 새 표 값으로 센다 (getSkillScore 와 같은 규칙) */
  if(!a && SCORE_VER === "v10") a = v11RoleSkill(cat, name);
  if(!a) return 0;
