/* SD_RULES 의 who 조건. x 는 calcSDBonus 가 만든 선수 정보 */
function sdWho(w, x) {
  if (!w) return true;
  if (w.selTeam && !x.selTeam) return false;
  if (w.stars && x.stars !== w.stars) return false;
  if (w.cards && w.cards.indexOf(x.ct) < 0 && !(w.potm && x.potm)) return false;
  if (w.league && x.league !== "*" && x.league !== w.league) return false;
  if (w.order && !(x.order >= w.order[0] && x.order <= w.order[1])) return false;
  if (w.pos === "starter" && !x.starter) return false;
  if (w.pos === "relief" && !x.relief) return false;
  if (w.pos === "infield" && x.outfield) return false;
  if (w.pos === "outfield" && !x.outfield) return false;
  return true;
}

/* 라이브 시너지는 라이브 · 국가대표 · 올스타 카드를 합쳐 7장 이상 (주전 · 후보 27칸).
   올스타도 라이브 시너지에 센다 (2026-10-19 사용자 확인 — 예전에는 라이브 · 국가대표만 셌다) */
var LIVE_SYN_TYPES = ["라이브", "국가대표", "올스타"];
function liveSynCount(counts) {
  var n = 0;
  LIVE_SYN_TYPES.forEach(function(t) { n += (counts && counts[t]) || 0; });
  return n;
}

function calcSDBonus(pl, slot, sdState, totalSP, batOrderIdx) {
  if (!pl) return {p:0,a:0,e:0,n:0,c:0,s:0};
  pl = applyTeamFlags(pl, sdState && sdState.teamName);
  var potm = potmEffect(pl, sdState);
  var isBat = pl.role === "타자";
  var ct = pl.cardType;
  var stars = pl.stars || 5;
  var isRP = (pl.position === "중계");
  var isCP = (pl.position === "마무리");
  var batSlots = ["C","1B","2B","3B","SS","LF","CF","RF","DH"];
  /* 타순 인덱스: batOrderIdx가 있으면 사용, 없으면 포지션 기준 (하위 호환) */
  var batIdx = (batOrderIdx !== undefined) ? batOrderIdx : batSlots.indexOf(slot);
  var isOF = (slot === "RF" || slot === "CF" || slot === "LF" || slot === "DH");
  var act = function(sp) { return totalSP >= sp; };

  /* 세트덱 구간 효과 (SD_RULES) */
  var S = { p: 0, a: 0, e: 0, n: 0, run: 0, def: 0, c: 0, s: 0, vel: 0, ctl: 0, sta: 0 };
  var x = { ct: ct, stars: stars, selTeam: isSelTeam(pl, sdState), league: sdLeagueOf(pl, sdState),
    order: isBat && batIdx >= 0 ? batIdx + 1 : 0, outfield: isBat && isOF,
    starter: !isBat && !isRP && !isCP, relief: !isBat && (isRP || isCP),
    /* POTM 이면 카드 종류와 상관없이 "라이브/스페셜 모두 적용" 구간을 받는다 */
    potm: !!potm.on };
  SD_RULES.forEach(function(r) {
    if (!act(r.sp)) return;
    var eff = isBat ? r.bat : r.pit;
    if (!eff) return;
    var got = sdSideOf(sdPick(sdState, r.sp));
    if (got.side !== r.side) return;
    if (r.year && ct !== "임팩트" && !(got.year && String(pl.year) === got.year)) return;
    if (!sdWho(r.who, x)) return;
    var keys = eff[0] === "*" ? (isBat ? SD_BAT_ALL : SD_PIT_ALL) : eff[0];
    keys.forEach(function(k) { S[k] += eff[1]; });
  });
  var bp = S.p, ba = S.a, be = S.e, bn = S.n, pc = S.c, ps = S.s;

  /* Synergy */
  var synCounts = sdState._synCounts || {};
  var autoLive = liveSynCount(synCounts) >= 7;
  var autoImp = (synCounts["임팩트"]||0) >= 5;
  var autoSig = (synCounts["시그니처"]||0) >= 5;
  var synLive = sdState.synLive !== undefined ? sdState.synLive : autoLive;
  var synImp = sdState.synImpact !== undefined ? sdState.synImpact : autoImp;
  var synSig = sdState.synSig !== undefined ? sdState.synSig : autoSig;
  /* 라이브 시너지 = 모두 +1, 임팩트 시너지 = 타자 +1, 시그니처 시너지 = 투수 +1.
     "+1" 은 능력치 전부다 — 점수에 안 쓰는 능력치도 같이 기록한다 */
  if (synLive) { bp++; ba++; be++; bn++; pc++; ps++; S.run++; S.def++; S.vel++; S.ctl++; S.sta++; }
  if (synImp && isBat) { bp++; ba++; be++; bn++; S.run++; S.def++; }
  if (synSig && !isBat) { pc++; ps++; S.vel++; S.ctl++; S.sta++; S.def++; }

  /* 국대에이스/포수리드: 종합점수에만 반영 (calcBat/calcPit에서 처리) */

  /* 유니폼 효과 (기본 +1) */
  bp += (sdState.uniP || 0);
  ba += (sdState.uniA || 0);
  be += (sdState.uniE || 0);
  bn += (sdState.uniN || 0);
  pc += (sdState.uniC || 0);
  ps += (sdState.uniS || 0);
  if (!isBat) S.ctl += (sdState.uniCtl || 0);

  /* 포지션 특훈 (POS_TRAIN 테이블 참조) */
  var ptData = sdState["pt_" + slot];
  var ptEntry = POS_TRAIN[slot];
  if (ptEntry) {
    /* 레벨 0 을 고른 것과 아직 안 정한 것은 다르다.
       || 로 걸러면 0 이 만렙으로 둔갑한다 — 저장값이 없을 때만 만렙으로 본다. */
    var ptLvRaw = (!ptData || ptData.level === undefined || ptData.level === null) ? ptEntry.mx : ptData.level;
    var ptLv = Math.min(ptLvRaw, ptEntry.mx);
    if (isBat) {
      var ptP = ptEntry["파워"]; bp += (ptP && ptLv < ptP.length ? ptP[ptLv] : 0) + (ptData ? ptData.r0 || 0 : 0);
      var ptA = ptEntry["정확"]; ba += (ptA && ptLv < ptA.length ? ptA[ptLv] : 0) + (ptData ? ptData.r1 || 0 : 0);
      var ptE = ptEntry["선구"]; be += (ptE && ptLv < ptE.length ? ptE[ptLv] : 0) + (ptData ? ptData.r2 || 0 : 0);
      var ptN = ptEntry["인내"]; bn += (ptN && ptLv < ptN.length ? ptN[ptLv] : 0) + (ptData ? ptData.r3 || 0 : 0);
    } else {
      var ptC = ptEntry["변화"]; pc += (ptC && ptLv < ptC.length ? ptC[ptLv] : 0) + (ptData ? ptData.r0 || 0 : 0);
      var ptS = ptEntry["구위"]; ps += (ptS && ptLv < ptS.length ? ptS[ptLv] : 0) + (ptData ? ptData.r1 || 0 : 0);
      /* 제구 — 자리마다 레벨별로 오른다(2026-10-21 캡처), 재설정도 된다(r2) */
      var ptK = ptEntry["제구"]; S.ctl += (ptK && ptLv < ptK.length ? ptK[ptLv] : 0) + (ptData ? ptData.r2 || 0 : 0);
    }
  }

  /* 주장 보너스 (라커룸에서 설정) */
  /* 주장(capBatId)은 타자·투수 누구나 지정할 수 있다. 고른 선수의 역할에 맞는 능력치가 오른다. */
  if (pl.id === sdState.capBatId) {
    if (isBat) { bp += sdState.capBatP || 0; ba += sdState.capBatA || 0; be += sdState.capBatE || 0; bn += sdState.capBatN || 0; }
    else { pc += sdState.capBatC || 0; ps += sdState.capBatS || 0; S.ctl += sdState.capBatCtl || 0; }
  }
  /* 투수조장은 투수만 */
  if (!isBat && pl.id === sdState.capPitId) { pc += sdState.capPitC || 0; ps += sdState.capPitS || 0; S.ctl += sdState.capPitCtl || 0; }

  /* 중계 전술 능력치 보너스 — 인게임 덱 화면의 수치로는 안 보이지만 경기에서는 실제로 오른다.
     승리조 · 추격조 전술을 따로 고른다 (2026-10-19, rpTactic · rpChaseTactic).
       승리조 적극 : 승리조 +1 / 승리조 분업 : 승리조 +3 (승리조가 3명일 때만)
       추격조 적극 : 추격조 +2
     — 2026년 10월 업데이트 값 (2026-10-22 사용자 지정, 예전엔 분업 +2 · 추격조 적극 +1). 구버전 점수는 예전 값 (RP_TAC_STAT)
     롱릴리프와 마무리는 어느 쪽에서도 받지 않는다.
     라인업에 보이는 능력치는 인게임 덱 화면의 수치와 같아야 하므로(스킬 · 전술로 오르는 것은 거기에 안 보인다)
     화면 능력치(c · s)에는 더하지 않고 따로 돌려준다(tac) — calcPit 이 종합점수에만 얹는다 (국대에이스 · 포수리드와 같은 식.
     2026-10-12 사용자 지정: 전에는 c · s 에 더해서 적극 · 분업을 켜면 라인업의 변화 · 구위 수치가 1 · 2씩 올라 보였다) */
  var tacB = 0;
  if (!isBat) {
    var rpGrp = rpGroupOf(slot, sdState.bpcIdx);
    if (rpGrp === "승리조") tacB = rpTacStat("승리조", rpTactic(sdState));
    else if (rpGrp === "패전조") tacB = rpTacStat("추격조", rpChaseTactic(sdState));
  }

  /* POTM 능력치 — 모든 능력치에 오른다 (potmEffect) */
  var potmB = potm.stat || 0;
  if (potmB) {
    if (isBat) { bp += potmB; ba += potmB; be += potmB; bn += potmB; S.run += potmB; S.def += potmB; }
    else { pc += potmB; ps += potmB; S.vel += potmB; S.ctl += potmB; S.sta += potmB; S.def += potmB; }
  }

  var ptSkillList = (sdState["pts_" + slot] || []).filter(function(x){ return !!x; });
  /* run · def · vel · sta 는 점수에 안 쓰고 효과만 담는다. ctl(제구)은 v1.1 부터 calcPit 이 점수에 쓴다 */
  return isBat ? {p:bp,a:ba,e:be,n:bn,run:S.run,def:S.def,ptSkills:ptSkillList,_sdState:sdState}
               : {c:pc,s:ps,tac:tacB,vel:S.vel,ctl:S.ctl,sta:S.sta,def:S.def,ptSkills:ptSkillList,_sdState:sdState};
}

