/* 시뮬레이션 결과(오름차순 정렬된 대용량 배열)를 N개 분위수 포인트로 압축
   입력: 길이 5만 배열, 출력: 길이 1000 배열 (0.1% 단위) */
function compressDist(d, N) {
  N = N || 1000;
  var out = {};
  Object.keys(d).forEach(function(key){
    var arr = d[key];
    if (!Array.isArray(arr) || arr.length === 0) { out[key] = arr; return; }
    if (arr.length <= N) { out[key] = arr.slice(); return; } /* 이미 작으면 그대로 */
    var compressed = new Array(N);
    for (var i = 0; i < N; i++) {
      var idx = Math.floor(i * arr.length / N);
      compressed[i] = Math.round(arr[idx] * 100) / 100;
    }
    out[key] = compressed;
  });
  return out;
}

function buildDist(skills, N) {
  N = N || 100000;
  var w = getW();
  var cats = ["타자","선발","중계","마무리"];
  var result = {};

  /* 스킬 분포는 여기서 만들지 않는다. 카드별 기본 레벨·1옵션 고정·국대 제한까지
     반영된 PREBUILT_SKILL_DIST(스킬 계산기와 공유) 를 그대로 쓴다. */

  /* 카드종류별 훈련 분포 추가 */
  var TRAIN_PTS = TRAIN_POINTS;
  var BAT_STATS_TR = ["파워","정확","선구","인내","주루","수비"];
  var PIT_STATS_TR = ["구속","변화","구위","제구","지구력","수비"];
  var w2 = getW();
  /* v1.1: 투수는 선발 · 불펜 가중치가 달라 칸을 나눈다 (pit = 선발, rp = 중계 · 마무리) */
  var PIT_ROLES = SCORE_VER === "v10" ? ["pit"] : ["pit", "rp"];
  ["bat"].concat(PIT_ROLES).forEach(function(role) {
    var isBatR = role === "bat";
    var pcat = role === "rp" ? "중계" : "선발";
    var statList = isBatR ? BAT_STATS_TR : PIT_STATS_TR;
    Object.keys(TRAIN_PTS).forEach(function(ct) {
      var total = TRAIN_PTS[ct];
      var fixList = ct === "시그니처" ? (isBatR ? ["주루","수비"] : ["구속","수비"]) : ["수비"];
      var freeList = statList.filter(function(s){ return fixList.indexOf(s)<0; });
      var scores = [];
      for (var i = 0; i < N; i++) {
        var dist = {};
        statList.forEach(function(s){dist[s]=0;});
        for (var t2=0;t2<total;t2++) dist[statList[Math.floor(Math.random()*statList.length)]]++;
        var sortedS = statList.slice().sort(function(a,b){return dist[a]-dist[b];});
        var toFix = sortedS.slice(0,fixList.length);
        var fixedTot = toFix.reduce(function(a,s){return a+dist[s];},0);
        var rem = total - fixedTot;
        var newDist = {}; statList.forEach(function(s){newDist[s]=0;});
        /* 가장 낮은 값 → 수비/주루+수비로 이동 */
        fixList.forEach(function(dest,idx){ newDist[dest]=dist[toFix[idx]]||0; });
        /* 나머지 재분배 */
        for(var r2=0;r2<rem;r2++) newDist[freeList[Math.floor(Math.random()*freeList.length)]]++;
        var sc = isBatR
          ? (newDist["파워"]||0)*w2.p+(newDist["정확"]||0)*w2.a+(newDist["선구"]||0)*w2.e+(newDist["인내"]||0)*(w2.n||0)
          : pitStatScore(pcat, newDist["변화"], newDist["구위"], newDist["제구"]);
        scores.push(Math.round(sc*100)/100);
      }
      scores.sort(function(a,b){return a-b;});
      result["train_"+role+"_"+ct] = scores;
    });
  });

  /* 특훈 분포 추가
     가능 카드: 골든글러브/시그니처/임팩트/국가대표
     시행횟수(specTrialsOf): 골든글러브/시그니처/임팩트=3, 국가대표=4,
       FA(임팩트/시그니처)·와일드카드(국가대표)는 2회 더
     임팩트: perfect 없음 (good/great 각 1/2)
     others: good/great/perfect 각 1/3
     기본값: 시행횟수만큼 타자 파워 / 투수 구위 (국가대표 +4, 와일드카드 +6)
     각 시행: good=1점, great=2점, perfect=3점 → 각 점수를 1씩 랜덤 스탯에 배정 */
  var SPEC_CARDS = Object.keys(SPEC_TRIALS);
  var BAT_SPEC_STATS = ["파워","정확","선구","인내","주루","수비"];
  var PIT_SPEC_STATS = ["구속","변화","구위","제구","지구력","수비"];
  var w3 = getW();

  SPEC_CARDS.forEach(function(ct) {
    var specRoles = ["bat"].concat(PIT_ROLES);
    specRoles.concat(specRoles.map(function (r) { return r + "_fa"; }), specRoles.map(function (r) { return r + "_wc"; })).forEach(function(roleKey) {
      var pcat2 = roleKey.indexOf("rp") === 0 ? "중계" : "선발";
      var isFa = roleKey.indexOf("_fa") >= 0;
      var isWc = roleKey.indexOf("_wc") >= 0;
      var isBatR = roleKey.indexOf("bat") >= 0;
      /* FA는 임팩트/시그니처, 와일드카드는 국가대표만 */
      if (isFa && !FA_CARDS[ct]) return;
      if (isWc && !WILDCARD_CARDS[ct]) return;
      var trials = specTrialsOf({ cardType: ct, isFa: isFa, isWildcard: isWc });
      var hasPerfect = ct !== "임팩트";
      var statList = isBatR ? BAT_SPEC_STATS : PIT_SPEC_STATS;
      /* 기본값: 타자 파워, 투수 구위 */
      var baseStatIdx = isBatR ? 0 : 2; /* 파워=0, 구위=2 */
      var baseVal = trials;

      var scores = [];
      for (var i = 0; i < N; i++) {
        var pts = {}; statList.forEach(function(s){pts[s]=0;});
        /* 기본값 고정 */
        pts[statList[baseStatIdx]] += baseVal;

        for (var t3 = 0; t3 < trials; t3++) {
          var roll = Math.random();
          var points;
          if (hasPerfect) {
            points = roll < 1/3 ? 1 : roll < 2/3 ? 2 : 3; /* good/great/perfect */
          } else {
            points = roll < 0.5 ? 1 : 2; /* good/great only (임팩트) */
          }
          /* 각 포인트를 개별적으로 랜덤 스탯에 배정 */
          for (var pp = 0; pp < points; pp++) {
            pts[statList[Math.floor(Math.random()*statList.length)]]++;
          }
        }
        var sc = isBatR
          ? (pts["파워"]||0)*w3.p+(pts["정확"]||0)*w3.a+(pts["선구"]||0)*w3.e+(pts["인내"]||0)*(w3.n||0)
          : pitStatScore(pcat2, pts["변화"], pts["구위"], pts["제구"]);
        scores.push(Math.round(sc*100)/100);
      }
      scores.sort(function(a,b){return a-b;});
      result["spec_"+roleKey+"_"+ct] = scores;
    });
  });

  return result;
}

function getPercentile(dist, value) {
  if (!dist || !dist.length) return null;
  /* 상위 몇 % = 내 값보다 낮은 비율 */
  var lo = 0; var hi = dist.length - 1;
  while (lo < hi) { var mid = (lo+hi+1)>>1; if (dist[mid] <= value) lo=mid; else hi=mid-1; }
  var rank = lo / dist.length * 100;
  var top = 100 - rank;
  return Math.max(0.1, Math.round(top * 10) / 10);
}

function LineupAnalysis(p) {
  var mob = p.mobile;
  var players = p.players || [];
  var lineupMap = p.lineupMap || {};
  var skills = p.skills || {};
  var sdState = p.sdState || {};
  var w = getW();

  var _role = React.useState("타자"); var role = _role[0]; var setRole = _role[1];

  /* 훈련·특훈 분포는 오프라인에서 구워 박아둔 것을 그대로 쓴다.
     웹에서 다시 굽는 경로는 두지 않는다 — data/gendist2.mjs 로 구워 PREBUILT_DIST 에 붙인다. */
  var dist = PREBUILT_DIST;

  /* 라인업 선수 추출 */
  var allSlots = Object.keys(lineupMap);
  var batSlots = ["C","1B","2B","3B","SS","LF","CF","RF","DH"];
  var pitSlots = ["SP1","SP2","SP3","SP4","SP5","RP1","RP2","RP3","RP4","RP5","RP6","CP"];

  var getpl = function(slot) {
    var pid = lineupMap[slot]; if (!pid) return null;
    var raw = players.find(function(x){ return x.id===pid; });
    /* FA·와일드카드는 덱 구단 기준 — 특훈 분포가 달라진다 */
    return raw ? deckPl(mergePl(raw)||raw, sdState) : null;
  };

  var batPlayers = batSlots.map(function(s){ return {slot:s, pl:getpl(s)}; }).filter(function(x){ return x.pl; });
  var pitPlayers = pitSlots.map(function(s){ return {slot:s, pl:getpl(s)}; }).filter(function(x){ return x.pl; });

  var getPitCat = function(pl) {
    var pos = pl.position || pl.subPosition || "";
    if (pos==="마무리"||pos==="CP") return "마무리";
    if (pos==="선발"||pos.indexOf("SP")>=0) return "선발";
    return "중계";
  };

  /* 1옵션을 고정하는 카드는 분포도 2·3옵션만으로 만들어져 있다 */
  var FIXED_FIRST_CARDS = ["임팩트", "올스타"];
  /* 데이터센터라 버프포함 값을 쓰고, 자동 레벨과 특훈 보너스도 라인업과 똑같이 계산한다 */
  var skillSc = function(pl, cat, slot, cmpOnly) {
    var mn = isLvManual(pl);
    var pts = (sdState["pts_" + slot] || []);
    var from = (cmpOnly && FIXED_FIRST_CARDS.indexOf(pl.cardType) >= 0) ? 2 : 1;
    var t = 0;
    for (var k = from; k <= 3; k++) {
      var nm = pl["skill" + k];
      if (!nm) continue;
      t += getSkillScore(nm, effSkillLv(nm, pl["s" + k + "Lv"], mn, pl.cardType, k, cat, pts), cat, true);
    }
    return t;
  };

  /* 점수에 무엇이 얼마씩 들어갔는지 — 툴팁으로 보여준다.
     버프 스킬이 버프 포함으로 들어갔는지, 표에 없는 이름인지, 레벨이 비었는지가 여기서 다 드러난다 */
  var skillParts = function(pl, cat, slot) {
    var mn = isLvManual(pl);
    var pts = (sdState["pts_" + slot] || []);
    var out = [];
    for (var k = 1; k <= 3; k++) {
      var nm = pl["skill" + k];
      if (!nm) { out.push(k + ". (비어 있음)"); continue; }
      var lv = effSkillLv(nm, pl["s" + k + "Lv"], mn, pl.cardType, k, cat, pts);
      if (!lv) { out.push(k + ". " + nm + " — 레벨이 비어 있어 0점으로 처리"); continue; }
      var raw = Math.round(getSkillScore(nm, lv, cat) * 100) / 100;
      var buf = Math.round(getSkillScore(nm, lv, cat, true) * 100) / 100;
      if (!buf) { out.push(k + ". " + nm + " Lv" + lv + " — 스킬표에 없는 이름이라 0점"); continue; }
      out.push(k + ". " + nm + " Lv" + lv + " = " + buf
               + (buf !== raw ? "  (팀 버프 포함. 라인업 개인 점수로는 " + raw + ")" : ""));
    }
    return out.join(String.fromCharCode(10));
  };
  var trainBat = function(pl) { return (pl.trainP||0)*w.p+(pl.trainA||0)*w.a+(pl.trainE||0)*w.e+(pl.trainN||0)*(w.n||0); };
  var trainPit = function(pl) { return pitStatScore(pitCatOf(pl), pl.trainC, pl.trainS, pl.trainCtl); };
  var specBat = function(pl) { return (pl.specPower||0)*w.p+(pl.specAccuracy||0)*w.a+(pl.specEye||0)*w.e+(pl.specPatience||0)*(w.n||0); };
  var specPit = function(pl) { return pitStatScore(pitCatOf(pl), pl.specChange, pl.specStuff, pl.specControl); };


  /* warn — 제구 미입력 투수의 훈련 %: 실제보다 낮게 나오니 주황으로 칠하고 옆에 적는다 */
  var pctBar = function(top, color, warn) {
    var w2 = Math.min(top, 100);
    var barColor = warn ? CTL_MISS_COLOR : top <= 5 ? "#FFD700" : top <= 20 ? "#66BB6A" : top <= 50 ? "#42A5F5" : "var(--td)";
    return (
      <div style={{display:"flex",alignItems:"center",gap:6,flex:1,minWidth:0,width:"100%"}}>
        <div style={{flex:1,minWidth:40,height:5,background:"var(--inner)",borderRadius:3,overflow:"hidden"}}>
          <div style={{width:(100-w2)+"%",height:"100%",background:barColor,borderRadius:3,transition:"width 0.4s"}} />
        </div>
        <span style={{fontSize:13,fontWeight:800,color:barColor,minWidth:50,flexShrink:0,textAlign:"right"}}>
          {top===null?"계산중":("상위 "+top+"%")}
        </span>
        {warn && (<span title={CTL_MISS_TIP} style={{fontSize:11,fontWeight:800,color:CTL_MISS_COLOR,whiteSpace:"nowrap",flexShrink:0,cursor:"help"}}>{"제구 미입력"}</span>)}
      </div>
    );
  };

  /* 시즌은 기본 스킬 레벨과 메이저 확률이 시그니처와 같아 같은 표를 쓴다 */
  var SKILL_DIST_ALIAS = { "시즌": "시그니처" };

  var renderRow = function(slot, pl, isBat) {
    var cat = isBat ? "타자" : getPitCat(pl);
    var skSc = Math.round(skillSc(pl, cat, slot)*100)/100;
    var fixedFirst = FIXED_FIRST_CARDS.indexOf(pl.cardType) >= 0;
    var cmpSc = fixedFirst ? Math.round(skillSc(pl, cat, slot, true)*100)/100 : skSc;
    var trSc = isBat ? Math.round(trainBat(pl)*100)/100 : Math.round(trainPit(pl)*100)/100;
    var spSc = isBat ? Math.round(specBat(pl)*100)/100 : Math.round(specPit(pl)*100)/100;
    /* 스킬 분포는 스킬 계산기와 같은 표를 쓴다 — 카드별 기본 레벨, 1옵션 고정,
       국대 스킬 제한, 포지션 제한, 좌우 변형이 모두 반영된 분포다 */
    var skPct = (function(){
      var ct = SKILL_DIST_ALIAS[pl.cardType] || pl.cardType;
      var key = skillDistKey(cat, ct, pl.hand, isBat && slot === "C");
      var arr = PREBUILT_SKILL_DIST[key];
      return arr ? pctFromDist(arr, cmpSc, PREBUILT_SKILL_TAIL[key]) : null;
    })();
    /* 훈련: 훈재분 계산기와 동일한 분포 사용 (카드종류별 다름) */
    var trainDist = dist ? dist["train_"+(isBat?"bat":pitDistRole(pl))+"_"+(pl.cardType||"")] : null;
    var trPct = trainDist ? getPercentile(trainDist, trSc) : null;
    /* 특훈: 카드종류별 분포 기반 — FA·와일드카드는 특훈이 2회 많은 분포 */
    var spPct = null;
    if (dist && specTrialsOf(pl)) {
      var specDist = dist[specDistKey(pl, isBat)];
      if (specDist) {
        /* 기본값(특훈 횟수만큼 파워·구위)보다 낮으면 상위 100% */
        var baseVal = specTrialsOf(pl);
        var baseScore = isBat ? baseVal*w.p : baseVal*getPW(pitCatOf(pl)).s;
        if (spSc < baseScore - 0.01) {
          spPct = 100;
        } else {
          spPct = getPercentile(specDist, spSc);
        }
      }
    }

    return (
      <div key={pl.id} style={{padding:"10px 12px",borderBottom:"1px solid var(--bd)",display:"flex",flexDirection:mob?"column":"row",gap:mob?6:12,alignItems:mob?"flex-start":"center"}}>
        <div style={{display:"flex",alignItems:"center",gap:8,minWidth:140}}>
          <Badge type={pl.cardType} />
          <div>
            <span style={{fontSize:14,fontWeight:800,color:"var(--t1)"}}>{pl.name}</span>
            <span style={{fontSize:11,color:"var(--td)",marginLeft:4}}>{slot}</span>
            <TeamFlagBadge pl={pl} ml={4} />
          </div>
        </div>
        <div style={{flex:1,display:"flex",flexDirection:"column",gap:4,width:"100%",minWidth:0}}>
          <div style={{display:"flex",alignItems:"center",gap:8,width:"100%"}}>
            <span style={{fontSize:12,color:"var(--td)",width:36,flexShrink:0}}>스킬</span>
            <span style={{fontSize:12,color:"var(--t2)",fontFamily:"var(--m)",width:36,flexShrink:0,cursor:"help",textDecoration:"underline dotted var(--bd)"}}
              title={skillParts(pl, cat, slot)
                     + (fixedFirst ? String.fromCharCode(10,10) + "1옵션을 고정하는 카드라 순위는 2·3옵션 " + cmpSc + " 으로 비교합니다" : "")}>
              {skSc}{fixedFirst ? "*" : ""}</span>
            {pctBar(skPct, "#CE93D8")}
          </div>
          <div style={{display:"flex",alignItems:"center",gap:8,width:"100%"}}>
            <span style={{fontSize:12,color:"var(--td)",width:36,flexShrink:0}}>훈련</span>
            <span style={{fontSize:12,color:"var(--t2)",fontFamily:"var(--m)",width:36,flexShrink:0}}>{trSc.toFixed(1)}</span>
            {pctBar(trPct, "#42A5F5", !isBat && ctlMissing(pl))}
          </div>
          <div style={{display:"flex",alignItems:"center",gap:8,width:"100%"}}>
            <span style={{fontSize:12,color:"var(--td)",width:36,flexShrink:0}}>특훈</span>
            <span style={{fontSize:12,color:"var(--t2)",fontFamily:"var(--m)",width:36,flexShrink:0}}>{spSc.toFixed(1)}</span>
            {spPct !== null ? pctBar(spPct) : <span style={{fontSize:12,color:"var(--td)"}}>{"해당없음"}</span>}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div>
      <div style={{display:"flex",gap:6,marginBottom:12,alignItems:"center",flexWrap:"wrap"}}>
        {["타자","투수"].map(function(r){ var a=r===role; return (
          <button key={r} onClick={function(){setRole(r);}} style={{padding:"6px 16px",fontSize:13,fontWeight:a?800:500,background:a?"var(--ta)":"var(--inner)",border:a?"1px solid var(--acc)":"1px solid var(--bd)",borderRadius:6,color:a?"var(--acc)":"var(--t2)",cursor:"pointer"}}>{r}</button>
        );})}
      </div>

      <div style={{background:"var(--card)",borderRadius:12,border:"1px solid var(--bd)",overflow:"hidden",marginBottom:6}}>
        <div style={{padding:"8px 12px",background:"var(--inner)",borderBottom:"1px solid var(--bd)",display:"flex",alignItems:"center",gap:6,flexWrap:"wrap"}}>
          <span style={{fontSize:14,fontWeight:800,color:"var(--t1)",whiteSpace:"nowrap"}}>{role==="타자"?"⚾ 타자 라인업":"⚾ 투수 라인업"}</span>
          <span style={{fontSize:12,color:"var(--td)",whiteSpace:"nowrap"}}>{"("+( role==="타자"?batPlayers.length:pitPlayers.length)+"명)"}</span>
          {/* 제구 미입력 — 폰은 제목이 쪼개지지 않게 한 줄 아래로 */}
          {role!=="타자" && (function(){ var n = pitPlayers.filter(function(x){ return ctlMissing(x.pl); }).length;
            return n > 0 ? (<span title={"이 투수들은 " + CTL_MISS_TIP} style={{fontSize:12,fontWeight:700,color:CTL_MISS_COLOR,cursor:"help",flexBasis:mob?"100%":"auto"}}>{(mob ? "" : "· ") + "제구 미입력 " + n + "명 — 훈련 % 가 실제보다 낮게 나와요"}</span>) : null; })()}
        </div>
        {(role==="타자"?batPlayers:pitPlayers).length === 0 ? (
          <div style={{padding:24,textAlign:"center",fontSize:13,color:"var(--td)"}}>{"라인업에 등록된 선수가 없습니다"}</div>
        ) : (role==="타자"?batPlayers:pitPlayers).map(function(x){ return renderRow(x.slot, x.pl, role==="타자"); })}
      </div>

      <div style={{padding:"8px 12px",background:"var(--inner)",borderRadius:8,fontSize:12,color:"var(--td)"}}>
        {"💡 스킬 분포는 카드별 기본 레벨·1옵션 고정·국대 제한까지 반영해 20만 회 굴린 표입니다. 팀 버프 스킬은 버프 포함 값으로 봅니다. 훈련·특훈은 5만 회 시뮬레이션 기반. "}
        <span style={{color:"#FFD700"}}>{"금색: 상위 5%"}</span>{" "}
        <span style={{color:"#66BB6A"}}>{"초록: 상위 20%"}</span>{" "}
        <span style={{color:"#42A5F5"}}>{"파랑: 상위 50%"}</span>
      </div>
    </div>
  );
}

